ne-height: 24px;\n  margin-top: 12px;\n  font-size: 14px;\n  line-height: 15px;\n  color: #000;\n  text-align: center;\n}\n.premium-payment-page .payment-footer[data-v-12bcabc8] {\n  margin-top: 24px;\n  text-align: center;\n  color: var(--color-secondary-text);\n  font-size: 13px;\n  line-height: 20px;\n}\n.payment-mode-list.need-wrap[data-v-12bcabc8] {\n  flex-wrap: wrap;\n  gap: 10px;\n}\n.payment-mode-list.need-wrap .payment-mode-item[data-v-12bcabc8] {\n  margin: 0 !important;\n}\n.payment-mode-item[data-v-12bcabc8] {\n  margin-left: 24px;\n}\n.payment-mode-item[data-v-12bcabc8]:first-child {\n  margin-left: 0;\n}\n.payment-mode-item.disabled[data-v-12bcabc8] {\n  opacity: 0.6;\n}\n@media screen and (max-width: 1024px) {\n.payment-mode-list[data-v-12bcabc8] {\n    flex-wrap: wrap;\n    min-width: 350px;\n    margin-top: 0;\n}\n.payment-mode-list .payment-mode-item[data-v-12bcabc8] {\n    margin: 5px !important;\n}\n}\n@media screen and (max-width: 425px) {\n.payment-mode-list[data-v-12bcabc8] {\n    justify-content: space-between !important;\n    width: 100%;\n    min-width: unset;\n}\n.payment-mode-list .payment-mode-item[data-v-12bcabc8] {\n    min-width: unset !important;\n    width: calc(100% / 2 - 10px) !important;\n}\n}\n@media screen and (max-width: 320px) {\n.payment-mode-list .payment-mode-item[data-v-12bcabc8] {\n    width: 100% !important;\n}\n}\n`,"",{version:3,sources:["webpack://./src/assets/less/payment-normal.less","webpack://./PaymentMode.vue","webpack://./src/assets/less/payment-premium.less","webpack://./src/components/payment/PaymentMode.vue"],names:[],mappings:"AAEA;EACE,qCAAA;EACA,4DAAA;EACA,+DAAA;EACA,+DAAA;EACA,6DAAA;EAEA,aAAA;EACA,YAAA;EACA,4BAAA;EACA,SAAA;EACA,4EAAA;EACA,uBAAA;ACFF;ADVA;EAeI,iBAAA;EACA,WAAA;ACFJ;ADdA;EAoBI,gBAAA;EACA,iBAAA;EACA,aAAA;ACHJ;ADKI;EACE,OAAA;EACA,iBAAA;EACA,mBAAA;EACA,qCAAA;EACA,aAAA;EACA,sBAAA;EACA,uCAAA;EACA,gBAAA;ACHN;AD7BA;EAoCM,kBAAA;EACA,gBAAA;EACA,eAAA;EACA,gBAAA;EACA,iBAAA;ACJN;ADpCA;EA4CM,aAAA;EACA,