EACA,6EAAA;ADyOR;ACneA;EA8PQ,cAAA;EAEA,WAAA;EACA,YAAA;EACA,iBAAA;ADuOR;ACzeA;EAqQQ,6EAAA;ADuOR;AC5eA;EAyQQ,6EAAA;ADsOR;AC/eA;EA6QQ,6EAAA;ADqOR;AClfA;EAiRQ,6EAAA;ADoOR;ACrfA;EAsRM,YAAA;EACA,YAAA;EACA,cAAA;EACA,gBAAA;EAEA,eAAA;EACA,kBAAA;EAEA,WAAA;EACA,kBAAA;EACA,gCAAA;EAEA,eAAA;EACA,gBAAA;EACA,iBAAA;EACA,kBAAA;AD+NN;AC7NM;EACE,YAAA;EACA,mBAAA;AD+NR;AC5NM;EACE,sCAAA;AD8NR;AC3NM;EACE,aAAA;EACA,oCAAA;AD6NR;AC3NQ;EACE,WAAA;EACA,kBAAA;EACA,WAAA;EACA,6EAAA;AD6NV;ACrhBA;EA8TM,iBAAA;EACA,gBAAA;EACA,eAAA;EACA,iBAAA;EACA,WAAA;EACA,kBAAA;AD0NN;AC7hBA;EAwUI,gBAAA;EAEA,kBAAA;EAEA,kCAAA;EAEA,eAAA;EACA,iBAAA;ADqNJ;AEjiBE;EACE,eAAA;EACA,SAAA;AFmiBJ;AEriBE;EAKI,oBAAA;AFmiBN;AE9hBA;EACE,iBAAA;AFgiBF;AE9hBE;EACE,cAAA;AFgiBJ;AE7hBE;EACE,YAAA;AF+hBJ;AE3hBA;AACE;IACE,eAAA;IACA,gBAAA;IACA,aAAA;AF6hBF;AEhiBA;IAMI,sBAAA;AF6hBJ;AACF;AEzhBA;AACE;IACE,yCAAA;IACA,WAAA;IACA,gBAAA;AF2hBF;AE9hBA;IAMI,2BAAA;IACA,uCAAA;AF2hBJ;AACF;AEvhBA;AACE;IAEI,sBAAA;AFwhBJ;AACF",sourcesContent:["@import \"@/assets/images/payment/payment.less\";\n\n.normal-payment-page {\n  --right-pane-footer-bg-color: #eef7fe;\n  --coupon-left-image: url('../images/payment/coupon-left.png');\n  --coupon-content-image: url('../images/payment/coupon-content.png');\n  --coupon-divider-image: url('../images/payment/coupon-divider.png');\n  --coupon-right-image: url('../images/payment/coupon-right.png');\n\n  display: flex;\n  width: 100vw;\n  min-height: var(--vh, 100vh);\n  margin: 0;\n  background: @normal-background;\n  justify-content: center;\n\n  .main-content {\n    max-width: 1200px;\n    width: 100%;\n  }\n\n  .goods-pane {\n    margin-top: 10px;\n    min-height: 460px;\n    display: flex;\n\n    &__right {\n      flex: 1;\n      margin-left: 24px;\n      border-radius: 14px;\n      background: rgba(255, 255, 255, 0.36);\n      display: flex;\n      flex-direction: column;\n      max-height: var(--right-bar-max-height);\n      overflow: hidden;\n    }\n\n    .goods-pane-title {\n      text-align: center;\n      font-weight: